inline bool Encoder::blob(const void* data, uint32_t bytes) {
  if (bytes && !data) { m_valid = false; return false; }
  auto* pointer = reserveBlob(bytes);
  if (!pointer) { return false; }
  if (bytes) { std::memcpy(pointer, data, bytes); }
  count(m_writer->metrics.copiedBytes, bytes);
  return true;
}
inline void Encoder::abort() {
  if (m_writer) { m_writer->m_active = false; m_writer = nullptr; }
  m_valid = false;
}
inline Encoder::~Encoder() { abort(); }
inline Result Encoder::finish(bool publish) {
  if (!m_writer || !m_valid || !m_writer->m_channel.healthy()) { abort(); return Result::Invalid; }
  auto* writer = m_writer;
  if (writer->m_channel.shared().cold.consumerClosed.load(std::memory_order_acquire)) {
    writer->m_channel.fault(Fault::PeerExited); abort(); return Result::Fault;
  }
  m_record.bytes = m_offset;
  m_record.bodyBytes = m_offset - sizeof(Record);
  std::memcpy(m_begin, &m_record, sizeof(m_record));
  writer->m_bytes += m_offset;
  ++writer->m_records; writer->m_active = false;
  count(writer->metrics.records);
  m_writer = nullptr; m_valid = false;
  return publish ? writer->flush() : Result::Success;
}

class Message {
  const uint8_t* m_data;
  uint32_t m_offset = 0;
  bool m_valid = true;
public:
  const Record header;
  Message(const Record& h, const uint8_t* data) : m_data(data), header(h) { }
  bool scalar(uint32_t& value) {
    if (!m_valid || sizeof(value) > header.bodyBytes - m_offset) { m_valid = false; return false; }
    std::memcpy(&value, m_data + m_offset, sizeof(value)); m_offset += sizeof(value); return true;
  }
  bool blob(const uint8_t*& data, uint32_t& bytes) {
    data = nullptr;
    if (!scalar(bytes) || bytes > UINT32_MAX - 3 || aligned(bytes) > header.bodyBytes - m_offset) {
      m_valid = false; return false;
    }
    data = m_data + m_offset; m_offset += aligned(bytes); return true;
  }
  bool complete() const { return m_valid && m_offset == header.bodyBytes; }
};

class Reader {
  Channel& m_channel;
  uint32_t m_sequence = 0;
  uint32_t m_timeout, m_spins;
public:
  Metrics metrics;
  Reader(Channel& channel, uint32_t timeoutMs = 1000, uint32_t spins = 0)
    : m_channel(channel), m_timeout(timeoutMs), m_spins(spins) {
    uint32_t empty = 0;
    if (!channel.shared().cold.consumerPid.compare_exchange_strong(empty, processId())) {
      throw std::runtime_error("duplicate channel reader");
    }
    m_sequence = channel.shared().consumer.completed.load();
  }
  Reader(const Reader&) = delete;
  ~Reader() {
    m_channel.shared().cold.consumerClosed.store(1, std::memory_order_seq_cst); m_channel.notifyCredits();
  }
  template<typename Handler> Result consume(Handler&& handler) {
    auto& shared = m_channel.shared();
    uint32_t published = shared.producer.published.load(std::memory_order_acquire);
    if (published == m_sequence) {
      const auto result = m_channel.wait(false, [&]() {
        published = shared.producer.published.load(std::memory_order_seq_cst);
        return published != m_sequence || !m_channel.healthy(std::memory_order_seq_cst) || shared.cold.producerClosed.load(std::memory_order_seq_cst);
      }, m_timeout, m_spins, shared.cold.producerPid.load(std::memory_order_acquire), metrics);
      if (result != Result::Success) { return result; }
    }
    if (!m_channel.healthy()) { return Result::Fault; }
    if (published == m_sequence && shared.cold.producerClosed.load(std::memory_order_acquire)) { return Result::Closed; }
    auto& block = m_channel.block(m_sequence);
    if (static_cast<uint32_t>(published - m_sequence) > shared.config.blockCount
        || block.sequence != m_sequence || block.bytes > shared.config.blockBytes || !block.records
        || block.records > block.bytes / sizeof(Record)) {
      m_channel.fault(Fault::Protocol); return Result::Fault;
    }
    uint32_t offset = 0;
    for (uint32_t i = 0; i < block.records; ++i) {
      if (sizeof(Record) > block.bytes - offset) { m_channel.fault(Fault::Bounds); return Result::Fault; }
      Record header {};
      std::memcpy(&header, m_channel.data(block) + offset, sizeof(header));
      if (header.bytes < sizeof(Record) || header.bytes > block.bytes - offset || header.bytes % 4
          || header.bodyBytes != header.bytes - sizeof(Record)) {
        m_channel.fault(Fault::Bounds); return Result::Fault;
      }
      Message message(header, m_channel.data(block) + offset + sizeof(Record));
      try {
        if (!handler(message) || !message.complete()) { m_channel.fault(Fault::Handler); return Result::Fault; }
      } catch (...) { m_channel.fault(Fault::Handler); return Result::Fault; }
      offset += header.bytes; count(metrics.records);
    }
    if (offset != block.bytes) { m_channel.fault(Fault::Bounds); return Result::Fault; }
    // All handlers and pointer reads finish before the entire block is reusable.
    shared.consumer.completed.store(++m_sequence, std::memory_order_seq_cst);
    count(metrics.blocks);
    if (!m_channel.notifyCredits()) { m_channel.fault(Fault::SystemWait); return Result::SystemFailure; }
    return Result::Success;
  }
};
